 f.push(polygon('green',[[-300,105],[-220,90],[-130,112],[-50,88],[20,72],[110,67],[183,90],[300,52],[300,86],[180,121],[100,101],[20,111],[-65,141],[-140,161],[-220,141],[-300,156]]));
