 f.push(polygon('green',rect(175,-100,100,115)),polygon('green',rect(-20,-65,74,93)),polygon('green',rect(-240,250,190,35)));
 for(let i=0;i<9;i++){let pts=[];for(let j=0;j<=50;j++){let a=j/50*Math.PI*2;pts.push([Math.max(-299,Math.min(299,-205+Math.cos(a)*(38+i*18))),Math.max(-299,Math.min(299,-220+Math.sin(a)*(25+i*13)))]);}f.push({layer:'terrain',type:'line',ring:pts,contour:true});}
