 const blocks=[[-78,-286,148,62],[112,-286,70,62],[225,-286,64,62],[-275,-106,153,103],[-60,-80,130,49],[117,-90,60,58],[225,-90,60,50],[-285,60,160,30],[-250,260,190,29],[0,263,115,26],[170,249,117,40]];
 blocks.forEach(([x,y,w,h])=>{for(let xx=x;xx<x+w-15;xx+=30+rand()*9)for(let yy=y;yy<y+h-14;yy+=31+rand()*8){const bw=Math.min(17+rand()*16,x+w-xx),bh=Math.min(18+rand()*16,y+h-yy),height=10+Math.pow(rand(),2)*87;f.push(polygon('buildings',rect(xx,yy,bw,bh),height));}});
 f.push(polygon('buildings',[[-54,-170],[-20,-170],[-20,-143],[5,-143],[5,-123],[-54,-123]],63),polygon('buildings',rect(130,-175,37,41),112),polygon('buildings',rect(236,-173,41,32),48));
