 const visible=state.layers.filter(l=>l.visible),extent=600;
 const scale=(flat?1.05:Math.min(.98,590/(extent*sp+gap*Math.max(0,visible.length-1)+120*cp)))*zoom;
 const baseY=flat?455:compact?530:555;
 const transform=(p,l)=>{let x=p[0]*unit,y=p[1]*unit,a=l.rotation*Math.PI/180;return [x*Math.cos(a)-y*Math.sin(a)+l.x*unit,x*Math.sin(a)+y*Math.cos(a)+l.y*unit]};
