   const h=flat?0:(f.height||0)*unit*state.heightScale;
   const bottom=f.ring.map(p=>project(p,z)),top=f.ring.map(p=>project(p,z+h));
   if(h>0){const sides=[];for(let i=0;i<f.ring.length;i++){let j=(i+1)%f.ring.length;let depth=(f.ring[i][0]+f.ring[j][0])*s+(f.ring[i][1]+f.ring[j][1])*c;sides.push({depth,p:[bottom[i],bottom[j],top[j],top[i]],color:shade(l.color,i%2?.78:.91)});}sides.sort((a,b)=>a.depth-b.depth).forEach(side=>grp.append(el('polygon',{points:coords(side.p),fill:side.color,stroke:state.showOutline?shade(side.color,.9):'none','stroke-width':.4})));}
   grp.append(el('path',{d:path([top,...f.holes.map(r=>r.map(p=>project(p,z+h)))]),'fill-rule':'evenodd',fill:l.id==='buildings'?shade(l.color,.88+Math.min(1,(f.height||0)/90)*.3):l.color,stroke:state.showOutline?shade(l.color,.78):'none','stroke-width':l.id==='terrain'?.6:.4}));
