 const main=document.createElement('button');main.className='layer-main';main.setAttribute('aria-pressed',String(l.id===state.selected));const dot=document.createElement('span');dot.className='layer-dot';dot.style.background=l.color;const text=document.createElement('span'),title=document.createElement('strong'),sub=document.createElement('small');title.textContent=l.name;sub.textContent=l.en;text.append(title,sub);main.append(dot,text);main.onclick=()=>{state.selected=l.id;renderLayers();syncControls()};
 const order=document.createElement('div');order.className='order-buttons';for(const[mark,direction]of[['↑',1],['↓',-1]]){const b=document.createElement('button');b.textContent=mark;b.setAttribute('aria-label',l.name+'を'+(direction===1?'上':'下')+'へ');let i=state.layers.indexOf(l);b.disabled=i+direction<0||i+direction>=state.layers.length;b.onclick=()=>{[state.layers[i],state.layers[i+direction]]=[state.layers[i+direction],state.layers[i]];renderLayers();schedule()};order.append(b)}row.append(eye,main,order);list.append(row);
