function syncControls(){const l=state.layers.find(l=>l.id===state.selected);$('selectedName').textContent=l.name;$('opacity').value=l.opacity*100;$('opacityValue').textContent=Math.round(l.opacity*100)+'%';$('layerColor').value=l.color;$('offsetX').value=l.x;$('offsetY').value=l.y;$('layerRotation').value=l.rotation;$('selectionStatus').textContent=l.name+'を編集中';$('separation').value=state.separation;$('separationValue').textContent=state.separation;$('heightScale').value=state.heightScale;$('heightScaleValue').textContent=state.heightScale.toFixed(2).replace(/0$/,'')+'×';$('showLabels').checked=state.showLabels;$('showOutline').checked=state.showOutline;$('titleInput').value=state.title;$('notesInput').value=state.notes;$('projectLabel').textContent=state.title;$('dataBadge').textContent=state.sample?'SAMPLE':'IMPORTED';$('contextNote').textContent=state.sample?'操作用の架空敷地 · 600 × 600 m\n実在の土地・建物を示すものではありません。':`${state.source} · 範囲 約${Math.round(state.extent)} m\n高さ属性のない建物は仮の高さ12 mで表示。`;document.querySelectorAll('[data-palette]').forEach(b=>b.classList.toggle('active',b.dataset.palette===state.palette));}
function setMode(mode){state.mode=mode;$('canvasWrap').hidden=mode==='sheet';$('sheetWrap').hidden=mode!=='sheet';document.querySelectorAll('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===mode);b.setAttribute('aria-pressed',String(b.dataset.mode===mode))});$('sceneTitle').textContent=mode==='2d'?'敷地の関係を、俯瞰する。':'敷地の構造を、ほどく。';schedule();}
function renderSheet(){$('sheetTitle').textContent=state.title;$('sheetSubtitle').textContent=`敷地を構成する、${state.layers.filter(l=>l.visible).length}つのレイヤー。`;$('sheetMain').replaceChildren(makeDiagram({compact:true}));$('sheetPlan').replaceChildren(makeDiagram({flat:true,labels:false,compact:true}));$('sheetText').textContent=state.notes;$('sheetCredit').textContent=state.sample?'SAMPLE SITE / 架空敷地 — 概念図':`${state.source} / 高さ未設定の建物は仮値`;$('sheetLegend').className='sheet-legend';$('sheetLegend').replaceChildren();state.layers.filter(l=>l.visible).forEach(l=>{let s=document.createElement('span'),i=document.createElement('i');i.style.background=l.color;s.append(i,document.createTextNode(l.name));$('sheetLegend').append(s)});}
