function download(blob,filename){let a=document.createElement('a'),u=URL.createObjectURL(blob);a.href=u;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(u),10000);}
function exportName(ext){return (state.title.replace(/[<>:"/\\|?*]/g,'_')||'strata')+'.'+ext;}
