function validateFeatures(features){if(!Array.isArray(features)||!features.length||features.length>3000)throw Error('要素数は1〜3,000件にしてください。');let points=0;for(const f of features){if(!definitions.some(d=>d[0]===f.layer)||!['line','polygon'].includes(f.type))throw Error('未対応のレイヤーまたは形状です。');for(const r of[f.ring,...(f.holes||[])]){if(!Array.isArray(r)||r.length<(f.type==='polygon'?3:2))throw Error('座標の数が足りません。');for(const p of r){if(!Array.isArray(p)||p.length<2||!Number.isFinite(p[0])||!Number.isFinite(p[1])||Math.abs(p[0])>1e8||Math.abs(p[1])>1e8)throw Error('座標が不正です。');points++}}if(points>100000)throw Error('座標点が多すぎます。範囲を絞ってください。');if(f.height!==undefined&&(!Number.isFinite(f.height)||f.height<0||f.height>3000))throw Error('建物高さは0〜3,000 mにしてください。');}return features;}
