function restoreProject(data){if(data.format!=='strata-project'||data.version!==1||!data.state)throw Error('対応していないプロジェクト形式です。');let s=data.state;validateFeatures(s.features);if(!Array.isArray(s.layers)||s.layers.length!==5||new Set(s.layers.map(l=>l.id)).size!==5)throw Error('レイヤー構成が不正です。');for(const l of s.layers){if(!definitions.some(d=>d[0]===l.id)||!/^#[0-9a-f]{6}$/i.test(l.color)||typeof l.visible!=='boolean')throw Error('レイヤー情報が不正です。');for(const[k,min,max]of[['opacity',0,1],['x',-300,300],['y',-300,300],['rotation',-180,180]])if(!Number.isFinite(l[k])||l[k]<min||l[k]>max)throw Error('レイヤー設定が不正です。');const d=definitions.find(d=>d[0]===l.id);l.name=d[1];l.en=d[2];}
 for(const[k,min,max]of[['extent',1,50000],['separation',0,100],['heightScale',0,3],['zoom',.4,2.5],['angle',-10000,10000],['pitch',.25,1.35]])if(!Number.isFinite(s[k])||s[k]<min||s[k]>max)throw Error('表示設定が不正です。');if(!['3d','2d','sheet'].includes(s.mode)||!definitions.some(d=>d[0]===s.selected)||!paletteSets[s.palette])throw Error('表示形式が不正です。');if(typeof s.title!=='string'||typeof s.notes!=='string'||typeof s.source!=='string')throw Error('プロジェクトの文章が不正です。');return {...s,title:s.title.slice(0,60),notes:s.notes.slice(0,600),source:s.source.slice(0,160),sample:!!s.sample,showLabels:!!s.showLabels,showOutline:!!s.showOutline};}
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));
document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{state.zoom=1;state.angle=-.63;state.pitch=.57;state.separation=b.dataset.preset==='exploded'?65:0;state.heightScale=1;state.layers.forEach(l=>l.visible=true);setMode(b.dataset.preset==='plan'?'2d':'3d');syncControls();renderLayers();});
