for(const id of['showLabels','showOutline'])$(id).onchange=e=>{state[id]=e.target.checked;schedule()};
for(const[id,key,min,max]of[['opacity','opacity',0,100],['offsetX','x',-300,300],['offsetY','y',-300,300],['layerRotation','rotation',-180,180]])$(id).oninput=e=>{let value=Number(e.target.value);if(!Number.isFinite(value))return;value=Math.min(max,Math.max(min,value));let l=state.layers.find(l=>l.id===state.selected);l[key]=id==='opacity'?value/100:value;if(id==='opacity')$('opacityValue').textContent=value+'%';schedule()};
$('layerColor').oninput=e=>{state.layers.find(l=>l.id===state.selected).color=e.target.value;renderLayers();schedule()};
$('resetLayer').onclick=()=>{const l=state.layers.find(l=>l.id===state.selected);Object.assign(l,{x:0,y:0,rotation:0,opacity:1,color:paletteSets[state.palette][l.id]});syncControls();renderLayers();schedule();toast('レイヤーの表現をリセットしました')};
$('titleInput').oninput=e=>{state.title=e.target.value;$('projectLabel').textContent=state.title;if(state.mode==='sheet')renderSheet()};$('notesInput').oninput=e=>{state.notes=e.target.value;if(state.mode==='sheet')renderSheet()};
$('sheetButton').onclick=()=>setMode('sheet');$('resetView').onclick=()=>{state.angle=-.63;state.pitch=.57;state.zoom=1;schedule()};
function zoom(delta){state.zoom=Math.max(.4,Math.min(2.5,state.zoom+delta));schedule()};$('zoomIn').onclick=()=>zoom(.1);$('zoomOut').onclick=()=>zoom(-.1);
let drag=null;$('scene').addEventListener('pointerdown',e=>{if(state.mode==='2d')return;drag={x:e.clientX,y:e.clientY};$('scene').setPointerCapture(e.pointerId)});$('scene').addEventListener('pointermove',e=>{if(!drag)return;state.angle+=(e.clientX-drag.x)*.008;state.pitch=Math.max(.25,Math.min(1.35,state.pitch+(e.clientY-drag.y)*.005));drag={x:e.clientX,y:e.clientY};schedule()});for(const ev of['pointerup','pointercancel','lostpointercapture'])$('scene').addEventListener(ev,()=>drag=null);$('scene').addEventListener('wheel',e=>{e.preventDefault();zoom(e.deltaY>0?-.04:.04)},{passive:false});
$('helpButton').onclick=()=>$('helpDialog').showModal();$('exportButton').onclick=()=>$('exportDialog').showModal();document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
$('saveProject').onclick=()=>{download(new Blob([JSON.stringify({format:'strata-project',version:1,state})],{type:'application/json'}),exportName('strata.json'));toast('プロジェクトを保存しました。読み込みから再開できます。')};
$('importButton').onclick=()=>$('fileInput').click();$('fileInput').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5*1024*1024)throw Error('ファイルは5 MBまでです。');const data=JSON.parse(await file.text());if(data.format==='strata-project'){state=restoreProject(data);toast('保存したプロジェクトを読み込みました')}else{const result=parseGeoJSON(data);state={...state,features:result.features,extent:result.extent,sample:false,source:file.name.slice(0,160),title:file.name.replace(/\.(json|geojson)$/i,'').slice(0,60),layers:defaults(),palette:'botanical',zoom:1,notes:'',angle:-.63,pitch:.57};toast(`${result.features.length}要素を読み込みました${result.skipped?`（非対応 ${result.skipped}件を除外）`:''}${result.inferred?`。属性なし ${result.inferred}件は形状で仮分類。`:''}`)}renderLayers();syncControls();setMode(state.mode)}catch(err){toast('読み込めませんでした：'+err.message)}finally{e.target.value=''}};
$('exportSvg').onclick=()=>{download(new Blob([exportDiagram()],{type:'image/svg+xml;charset=utf-8'}),exportName('svg'));toast('SVGを書き出しました')};
$('exportPng').onclick=async()=>{const b=$('exportPng');b.disabled=true;let url;try{url=URL.createObjectURL(new Blob([exportDiagram()],{type:'image/svg+xml;charset=utf-8'}));const img=new Image();img.src=url;await img.decode();const canvas=document.createElement('canvas');canvas.width=2400;canvas.height=2040;canvas.getContext('2d').drawImage(img,0,0,2400,2040);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('画像の生成に失敗しました');download(blob,exportName('png'));toast('PNGを書き出しました')}catch(err){toast('画像を書き出せませんでした：'+err.message)}finally{if(url)URL.revokeObjectURL(url);b.disabled=false}};
$('exportPrint').onclick=()=>{$('exportDialog').close();setMode('sheet');renderSheet();requestAnimationFrame(()=>requestAnimationFrame(()=>window.print()))};
const sourceSection=document.createElement('section');sourceSection.className='source-section';sourceSection.innerHTML='<div class="source-heading"><span class="eyebrow">01A / SOURCES</span><span class="source-status">任意</span></div><button id="gsiButton" class="source-card"><span class="source-mark gsi-mark">GSI</span><span><strong>国土地理院</strong><small>地形・道路・建物外形</small></span><span class="source-arrow">↗</span></button><button id="plateauButton" class="source-card"><span class="source-mark plateau-mark">P.</span><span><strong>PLATEAU</strong><small>高さ・用途・都市の3D</small></span><span class="source-arrow">↗</span></button><p class="source-note">資料を読み込み、建築のレイヤーへ変換する。</p>';
document.querySelector('.context-note').after(sourceSection);const sourceStyle=document.createElement('style');sourceStyle.textContent='.source-section{border-top:1px solid var(--border);padding:18px 0 6px;margin-bottom:22px}.source-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:10px}.source-status{font-size:10px;color:var(--muted);border:1px solid var(--border);padding:3px 6px;border-radius:3px}.source-card{display:flex;align-items:center;gap:9px;width:100%;border:1px solid var(--border);padding:8px 7px;margin:6px 0;text-align:left;background:#fafbf9}.source-card:hover{background:#f1f5ed}.source-card strong{font-size:12px;font-weight:600}.source-card small{font-size:10px;margin-top:3px}.source-mark{display:grid;place-items:center;width:36px;height:32px;border-radius:4px;font-size:11px;font-weight:700;letter-spacing:-.05em}.gsi-mark{background:#e4f0de;color:#315d40}.plateau-mark{background:#dfe9f7;color:#274a74}.source-arrow{margin-left:auto;color:var(--muted)}.source-note{font-size:10px;line-height:1.7;color:var(--muted);margin-top:9px}.source-card.source-active{border-color:#7e9d6e;box-shadow:0 0 0 2px #e6f0dd}.source-section .eyebrow{font-size:10px}';document.head.append(sourceStyle);
const gsiUrl='https://maps.gsi.go.jp/';const plateauUrl='https://www.mlit.go.jp/plateau/';$('gsiButton').onclick=()=>{window.open(gsiUrl,'_blank','noopener,noreferrer');document.querySelector('.source-status').textContent='参照中';$('gsiButton').classList.add('source-active');toast('国土地理院を開きました。ダウンロードしたGeoJSONをここへ読み込めます。')};$('plateauButton').onclick=()=>{window.open(plateauUrl,'_blank','noopener,noreferrer');document.querySelector('.source-status').textContent='参照中';$('plateauButton').classList.add('source-active');toast('PLATEAUを開きました。書き出したGeoJSONをここへ読み込めます。')};
renderLayers();syncControls();setMode('3d');

// The optional browser tool interface shares the editor's state and rendering.
const toolContext=document.modelContext;
if(toolContext?.registerTool){
 const lifetime=new AbortController();
 const readState=()=>({mode:state.mode,separation:state.separation,heightScale:state.heightScale,title:state.title,sample:state.sample,features:state.features.length,layers:state.layers.map(({id,visible,color,opacity,x,y,rotation})=>({id,visible,color,opacity,x,y,rotation}))});
 const updateView=async input=>{
  if(!input||typeof input!=='object'||Array.isArray(input))throw Error('Expected an object');
  if(Object.keys(input).some(k=>!['mode','separation','heightScale','layer'].includes(k)))throw Error('Unknown setting');
  if(input.mode!==undefined&&!['3d','2d','sheet'].includes(input.mode))throw Error('Invalid view');
  for(const[k,min,max]of[['separation',0,100],['heightScale',0,3]])if(input[k]!==undefined&&(!Number.isFinite(input[k])||input[k]<min||input[k]>max))throw Error('Invalid '+k);
  let target=null;if(input.layer!==undefined){const l=input.layer;if(!l||typeof l!=='object'||Object.keys(l).some(k=>!['id','visible','opacity'].includes(k)))throw Error('Invalid layer');target=state.layers.find(x=>x.id===l.id);if(!target)throw Error('Unknown layer');if(l.visible!==undefined&&typeof l.visible!=='boolean')throw Error('Invalid visibility');if(l.opacity!==undefined&&(!Number.isFinite(l.opacity)||l.opacity<0||l.opacity>1))throw Error('Invalid opacity');}
  if(input.separation!==undefined)state.separation=input.separation;if(input.heightScale!==undefined)state.heightScale=input.heightScale;
  if(target){if(input.layer.visible!==undefined)target.visible=input.layer.visible;if(input.layer.opacity!==undefined)target.opacity=input.layer.opacity;state.selected=target.id;}
  renderLayers();syncControls();setMode(input.mode||state.mode);await new Promise(requestAnimationFrame);return readState();
 };
 const tools=[{name:'read_site_composition',description:'Read the current site diagram, layer settings and view. Does not change the document.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:readState},{name:'configure_site_composition',description:'Update the visible site diagram view, layer spacing, building height multiplier, or visibility and opacity of one existing layer. No files are exported or uploaded.',inputSchema:{type:'object',properties:{mode:{type:'string',enum:['3d','2d','sheet']},separation:{type:'number',minimum:0,maximum:100},heightScale:{type:'number',minimum:0,maximum:3},layer:{type:'object',properties:{id:{type:'string',enum:definitions.map(d=>d[0])},visible:{type:'boolean'},opacity:{type:'number',minimum:0,maximum:1}},required:['id'],additionalProperties:false}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:updateView}];
 for(const tool of tools){try{Promise.resolve(toolContext.registerTool(tool,{signal:lifetime.signal})).catch(()=>{});}catch{}}
 window.addEventListener('pagehide',()=>lifetime.abort(),{once:true});
}
